"""Cross-cutting HTTP behaviour that every Spendcheck service shares.

* X-Request-ID: generated by the gateway (or here if missing) and echoed back, so one user
  action can be traced through every container's logs.
* X-Process-Time-Ms: server-side time spent in this service. The system-level evaluation
  (proposal, Evaluation Plan "System level") reads this header from each hop to report
  per-container latency without extra instrumentation.
* X-User-Id: the gateway is the only component that knows who the user is. Services read the
  user from this header and never from the request body, so a client cannot ask about
  someone else's data by editing JSON.
"""

import logging
import time
import uuid

from fastapi import FastAPI, Header, HTTPException, Request

access_log = logging.getLogger("spendcheck.access")


def configure_logging(level: str = "INFO") -> None:
    """Plain one-line logs to stdout; Docker and Kubernetes collect stdout automatically."""
    logging.basicConfig(
        level=level,
        format="%(asctime)s %(levelname)s %(name)s %(message)s",
    )


def install_common_middleware(app: FastAPI, service_name: str) -> None:
    """Attach request-ID propagation and latency headers to `app`."""

    @app.middleware("http")
    async def _request_context(request: Request, call_next):
        request_id = request.headers.get("X-Request-ID") or uuid.uuid4().hex
        request.state.request_id = request_id
        start = time.perf_counter()

        response = await call_next(request)

        elapsed_ms = (time.perf_counter() - start) * 1000
        response.headers["X-Request-ID"] = request_id
        response.headers["X-Process-Time-Ms"] = f"{elapsed_ms:.1f}"
        response.headers["X-Service"] = service_name
        access_log.info(
            "service=%s request_id=%s method=%s path=%s status=%d ms=%.1f",
            service_name, request_id, request.method, request.url.path,
            response.status_code, elapsed_ms,
        )
        return response


def require_user_id(x_user_id: str | None = Header(default=None)) -> str:
    """FastAPI dependency: the caller's user ID, as set by the gateway."""
    if not x_user_id:
        raise HTTPException(status_code=401, detail="Missing X-User-Id header (set by the gateway)")
    return x_user_id
